function renderHistory(){if(!$("#auditList"))return;$("#auditList").innerHTML=state.audit.length?state.audit.slice(0,50).map(a=>`<div class="row"><div class="row-main"><div class="avatar">↺</div><div class="row-text"><strong>${esc(a.action)}</strong><span>${new Date(a.date).toLocaleString("pt-BR")}</span></div></div></div>`).join(""):emptyHtml("Nenhuma atividade registrada.");$("#trashList").innerHTML=state.trash.length?state.trash.map(t=>`<div class="row"><div class="row-main"><div class="avatar">×</div><div class="row-text"><strong>${esc(t.label)}</strong><span>${esc(t.collection)} · ${new Date(t.deletedAt).toLocaleString("pt-BR")}</span></div></div><button class="mini restore-btn" data-restore-trash="${t.id}">Restaurar</button></div>`).join(""):emptyHtml("A lixeira está vazia.")}
function softDelete(collection,item,label){state.trash.unshift({id:id("trash"),collection,item:structuredClone(item),label,deletedAt:new Date().toISOString()});state[collection]=state[collection].filter(x=>x.id!==item.id);save(`Excluído: ${label}`)}
function closeSelectedMonth(){const m=$("#closingMonth").value||month(),totals=monthly(m),snapshot={id:id("close"),month:m,createdAt:new Date().toISOString(),income:totals.inc,expense:totals.exp,accounts:state.accounts.map(a=>({id:a.id,name:a.name,balance:balance(a.id,`${m}-${new Date(+m.slice(0,4),+m.slice(5),0).getDate()}`)}))};snapshot.assets=snapshot.accounts.reduce((s,a)=>s+a.balance,0);snapshot.debt=debt();snapshot.netWorth=snapshot.assets-snapshot.debt;const old=state.closings.find(x=>x.month===m);if(old&&!confirm("Este mês já foi fechado. Substituir a fotografia?"))return;state.closings=state.closings.filter(x=>x.month!==m);state.closings.push(snapshot);save(`Fechamento registrado: ${m}`);render();toast("Fechamento mensal salvo.")}
function simulate(){const type=$("#simulationType").value,amount=+$("#simulationAmount").value,count=Math.max(1,+$("#simulationInstallments").value||1);if(!(amount>0))return toast("Informe um valor para simular.",true);const monthlyImpact=type==="purchase"||type==="loan"?amount/count:amount,months=Array.from({length:Math.min(12,count)},(_,i)=>monthAt(i+1));$("#simulationResult").innerHTML=`<p class="muted">Simulação sem alterar seus dados. Impacto mensal: <strong>${type==="income"?"+":"−"} ${money(monthlyImpact)}</strong>.</p><div class="simulation-grid">${months.map(m=>{const p=projectionForMonth(m),base=p.income-p.expense,adjusted=base+(type==="income"?monthlyImpact:-monthlyImpact);return`<div class="simulation-month"><span>${monthLabel(m)}</span><strong class="${adjusted<0?"negative":"positive"}">${money(adjusted)}</strong></div>`}).join("")}</div>`}
let pendingImport=[];
function parseStatement(text,name){const rows=[];if(name.toLowerCase().endsWith(".ofx")){const dates=[...text.matchAll(/<DTPOSTED>(\d{8})[\s\S]*?<TRNAMT>([-\d.,]+)[\s\S]*?<MEMO>([^<\r\n]*)/gi)];dates.forEach(m=>rows.push({date:`${m[1].slice(0,4)}-${m[1].slice(4,6)}-${m[1].slice(6,8)}`,amount:Number(m[2].replace(",",".")),description:m[3].trim()||"Extrato OFX"}))}else{text.split(/\r?\n/).slice(1).forEach(line=>{const cols=line.includes(";")?line.split(";"):line.split(",");if(cols.length<2)return;const raw=cols[0].trim(),parts=raw.split(/[\/-]/),dateValue=parts[0].length===4?`${parts[0]}-${parts[1].padStart(2,"0")}-${parts[2].padStart(2,"0")}`:`${parts[2]}-${parts[1].padStart(2,"0")}-${parts[0].padStart(2,"0")}`,amount=Number(cols[1].replace(/[^\d,.-]/g,"").replace(".","").replace(",","."));if(dateValue&&Number.isFinite(amount))rows.push({date:dateValue,amount,description:(cols[2]||"Importado do extrato").trim()})})}return rows.slice(0,500)}
function showImportPreview(){$("#confirmImportBtn").hidden=!pendingImport.length;$("#importPreview").innerHTML=pendingImport.length?pendingImport.slice(0,100).map(x=>`<div class="import-line"><span>${date(x.date)}</span><span>${esc(x.description)}</span><strong class="${x.amount<0?"negative":"positive"}">${money(x.amount)}</strong></div>`).join(""):""}
function exportReportCsv(){const end=$("#reportMonth").value||month(),months=monthSequence(end,+$("#reportRange").value||6),lines=[["Mês","Receitas","Despesas","Resultado"],...months.map(m=>{const x=monthly(m);return[m,x.inc.toFixed(2),x.exp.toFixed(2),(x.inc-x.exp).toFixed(2)]})],blob=new Blob(["\uFEFF"+lines.map(r=>r.join(";")).join("\n")],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`fontes-finance-relatorio-${end}.csv`;a.click();URL.revokeObjectURL(a.href)}
function runDiagnostics(){const checks=[];checks.push({name:"sequência mensal",ok:monthSequence("2026-03",3).join(",")==="2026-01,2026-02,2026-03"});const sample={id:"test",cardId:"none",total:100,installments:3,date:"2026-01-10",description:"Teste"},parts=installments(sample);checks.push({name:"soma das parcelas",ok:Math.abs(parts.reduce((s,x)=>s+x.amount,0)-100)<.001});checks.push({name:"chaves de recorrência",ok:occurrenceKey("a","2026-01-01")==="a|2026-01-01"});const failed=checks.filter(x=>!x.ok);if(failed.length)console.error("Fontes Finance: diagnóstico falhou",failed);else console.info("Fontes Finance: cálculos essenciais verificados.")}

document.addEventListener("click",e=>{const b=e.target.closest("button,[data-nav],[data-open]");if(!b)return;if(b.dataset.nav)return nav(b.dataset.nav);const open=b.dataset.open;if(open==="account")openAccount();if(open==="income")openTransaction("income");if(open==="expense")openTransaction("expense");if(open==="transfer")openTransfer();if(open==="purchase")openPurchase();if(open==="card")openCard();if(open==="loan")openLoan();if(open==="goal")openGoal();if(b.dataset.editAccount)openAccount(b.dataset.editAccount);if(b.dataset.editGoal)openGoal(b.dataset.editGoal);if(b.dataset.editTx){const t=state.transactions.find(x=>x.id===b.dataset.editTx);openTransaction(t.type,t.id)}if(b.dataset.editPurchase)openPurchase(null,b.dataset.editPurchase);if(b.dataset.buy)openPurchase(b.dataset.buy);if(b.dataset.payCard)payCard(b.dataset.payCard);if(b.dataset.payLoan)payLoan(b.dataset.payLoan);if(b.dataset.deleteAccount){const aid=b.dataset.deleteAccount,used=state.transactions.some(t=>t.accountId===aid||t.from===aid||t.to===aid)||state.loans.some(l=>l.accountId===aid);if(used)return toast("A conta possui movimentações e não pode ser excluída.",true);if(confirm("Excluir esta conta?")){state.accounts=state.accounts.filter(x=>x.id!==aid);save();render()}}if(b.dataset.deleteCard){const cid=b.dataset.deleteCard;if(state.purchases.some(x=>x.cardId===cid))return toast("Exclua as compras antes de remover o cartão.",true);if(confirm("Excluir cartão?")){state.cards=state.cards.filter(x=>x.id!==cid);save();render()}}if(b.dataset.deleteLoan){const lid=b.dataset.deleteLoan;if(state.loanPayments.some(x=>x.loanId===lid))return toast("Exclua os pagamentos antes.",true);if(confirm("Excluir empréstimo?")){state.loans=state.loans.filter(x=>x.id!==lid);save();render()}}if(b.dataset.deleteGoal&&confirm("Excluir meta?")){state.goals=state.goals.filter(x=>x.id!==b.dataset.deleteGoal);save();render()}if(b.dataset.deleteTx){const tid=b.dataset.deleteTx,type=b.dataset.type;if(!confirm(type==="card_purchase"?"Excluir esta compra e todas as suas parcelas?":"Excluir este registro?"))return;if(type==="card_purchase")state.purchases=state.purchases.filter(x=>x.id!==tid);else if(type==="card_payment")state.cardPayments=state.cardPayments.filter(x=>x.id!==tid);else if(type==="loan_payment")state.loanPayments=state.loanPayments.filter(x=>x.id!==tid);else state.transactions=state.transactions.filter(x=>x.id!==tid);save();render()}});
document.addEventListener("click",e=>{const b=e.target.closest("button,[data-open],[data-confirm-tx],[data-edit-card],[data-edit-budget],[data-delete-budget]");if(!b)return;if(b.dataset.open==="budget"){e.stopImmediatePropagation();openBudget();return}if(b.dataset.confirmTx){e.stopImmediatePropagation();setOccurrenceStatus(b.dataset.confirmTx,b.dataset.date,"confirmed");return}if(b.dataset.editCard){e.stopImmediatePropagation();openCard(b.dataset.editCard);return}if(b.dataset.editBudget){e.stopImmediatePropagation();openBudget(b.dataset.editBudget);return}if(b.dataset.deleteBudget){e.stopImmediatePropagation();if(confirm("Excluir este orçamento?")){state.budgets=state.budgets.filter(x=>x.id!==b.dataset.deleteBudget);save();render()}return}if(b.dataset.editTx){const t=state.transactions.find(x=>x.id===b.dataset.editTx);if(t?.recurring){e.stopImmediatePropagation();editRecurring(t.id,b.dataset.date);return}}if(b.dataset.deleteTx&&["income","expense"].includes(b.dataset.type)){const t=state.transactions.find(x=>x.id===b.dataset.deleteTx);if(t?.recurring){e.stopImmediatePropagation();deleteRecurring(t.id,b.dataset.date)}}},true);
document.addEventListener("click",e=>{const b=e.target.closest("[data-delete-tx],[data-delete-goal],[data-delete-budget],[data-delete-card],[data-delete-loan],[data-delete-account]");if(!b)return;let collection,item,label;if(b.dataset.deleteTx){const type=b.dataset.type;if(type==="card_purchase"){collection="purchases";item=state.purchases.find(x=>x.id===b.dataset.deleteTx)}else if(type==="card_payment"){collection="cardPayments";item=state.cardPayments.find(x=>x.id===b.dataset.deleteTx)}else if(type==="loan_payment"){collection="loanPayments";item=state.loanPayments.find(x=>x.id===b.dataset.deleteTx)}else{collection="transactions";item=state.transactions.find(x=>x.id===b.dataset.deleteTx);if(item?.recurring)return}label=item?.description||item?.name||"Movimentação"}else if(b.dataset.deleteGoal){collection="goals";item=state.goals.find(x=>x.id===b.dataset.deleteGoal);label=item?.name}else if(b.dataset.deleteBudget){collection="budgets";item=state.budgets.find(x=>x.id===b.dataset.deleteBudget);label=`Orçamento ${item?.category||""}`}else if(b.dataset.deleteCard){collection="cards";item=state.cards.find(x=>x.id===b.dataset.deleteCard);label=item?.name;if(state.purchases.some(x=>x.cardId===item?.id))return}else if(b.dataset.deleteLoan){collection="loans";item=state.loans.find(x=>x.id===b.dataset.deleteLoan);label=item?.name;if(state.loanPayments.some(x=>x.loanId===item?.id))return}else if(b.dataset.deleteAccount){collection="accounts";item=state.accounts.find(x=>x.id===b.dataset.deleteAccount);label=item?.name;const used=state.transactions.some(t=>t.accountId===item?.id||t.from===item?.id||t.to===item?.id)||state.loans.some(l=>l.accountId===item?.id);if(used)return}if(!item||!confirm("Mover este item para a lixeira?"))return;e.stopImmediatePropagation();softDelete(collection,item,label||"Item excluído");render();toast("Item movido para a lixeira.")},true);
