$("#closingMonth").value=month();$("#closeMonthBtn").onclick=closeSelectedMonth;$("#reconcileBtn").onclick=()=>{const aid=$("#reconcileAccount").value,real=+$("#reconcileReal").value,calculated=balance(aid),diff=real-calculated;$("#reconcileResult").innerHTML=`Saldo calculado: <strong>${money(calculated)}</strong><br>Diferença: <strong class="${diff<0?"negative":"positive"}">${money(diff)}</strong>`;$("#reconcileAdjustBtn").hidden=Math.abs(diff)<.005;$("#reconcileAdjustBtn").dataset.diff=diff;$("#reconcileAdjustBtn").dataset.account=aid};$("#reconcileAdjustBtn").onclick=()=>{const amount=+$("#reconcileAdjustBtn").dataset.diff,accountId=$("#reconcileAdjustBtn").dataset.account;if(!amount)return;state.transactions.push({id:id("adj"),type:amount>0?"income":"expense",amount:Math.abs(amount),accountId,category:"Outros",date:iso(),status:"confirmed",description:"Ajuste de conciliação"});save("Ajuste de conciliação criado");render();toast("Saldo conciliado.")};$("#simulateBtn").onclick=simulate;
$("#statementInput").onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;pendingImport=parseStatement(await file.text(),file.name);showImportPreview();toast(`${pendingImport.length} lançamentos encontrados.`)}catch{toast("Não foi possível ler o extrato.",true)}e.target.value=""};$("#confirmImportBtn").onclick=()=>{if(!pendingImport.length||!state.accounts.length)return toast("Cadastre uma conta antes de importar.",true);const aid=state.accounts[0].id;pendingImport.forEach(x=>state.transactions.push({id:id("imp"),type:x.amount>=0?"income":"expense",amount:Math.abs(x.amount),accountId:aid,category:"Outros",date:x.date,status:"planned",description:x.description}));save(`Extrato importado: ${pendingImport.length} itens`);pendingImport=[];showImportPreview();render();toast("Extrato importado como previsto para revisão.")};$("#exportReportCsv").onclick=exportReportCsv;$("#printReportBtn").onclick=()=>{nav("reports");setTimeout(()=>print(),100)};
$("#emptyTrashBtn").onclick=()=>{if(state.trash.length&&confirm("Esvaziar a lixeira permanentemente?")){state.trash=[];save("Lixeira esvaziada");render()}};document.addEventListener("click",e=>{const b=e.target.closest("[data-restore-trash]");if(!b)return;const entry=state.trash.find(x=>x.id===b.dataset.restoreTrash);if(!entry)return;state[entry.collection]??=[];state[entry.collection].push(entry.item);state.trash=state.trash.filter(x=>x.id!==entry.id);save(`Restaurado: ${entry.label}`);render();toast("Item restaurado.")});
